    public static func ==(lhs: ParsedEnvelope, rhs: ParsedEnvelope) -> Bool {
        if lhs.version != rhs.version {
            return false
        }
        if lhs.mode != rhs.mode {
            return false
        }
        if lhs.anonymous != rhs.anonymous {
            return false
        }
        if lhs.salt != rhs.salt {
            return false
        }
        if lhs.entries != rhs.entries {
            return false
        }
        if lhs.nonce != rhs.nonce {
            return false
        }
        if lhs.ciphertext != rhs.ciphertext {
            return false
        }
        if lhs.header != rhs.header {
